import{z as i,x as A,o as e,c as B,q as n,j as s,D as E,d as r,s as t,S as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"统一理解与生成 Janus / Show-o","description":"","frontmatter":{"title":"统一理解与生成 Janus / Show-o","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/unified-understanding-generation.md","filePath":"llm/unified-understanding-generation.md","lastUpdated":1791413859000}'),d={name:"llm/unified-understanding-generation.md"};function h(p,a,m,u,C,_){const o=A("Mermaid");return e(),B("div",null,[a[2]||(a[2]=n('<h1 id="统一理解与生成-janus-show-o" tabindex="-1">统一理解与生成 Janus / Show-o <a class="header-anchor" href="#统一理解与生成-janus-show-o" aria-label="Permalink to &quot;统一理解与生成 Janus / Show-o&quot;">​</a></h1><div class="epigraph"><p>同一套语言模型权重既要谈图又要造图。视觉编码器若为理解优化，量化码就伤 OCR；若为码本优化，谈图又变盲。</p><footer>—— Wu 等 Janus（解耦视觉编码）；Xie 等 Show-o；对照 Chameleon 的统一离散 token</footer></div><p><a href="/llm/mar-masked-ar">上一课</a>表明生成可以走连续。<a href="/llm/continuous-vs-discrete-vision-tokens">连续对离散</a> 已把轴钉死。缺口是产品形态：一个模型、两套任务。Janus 拆视觉编码；Show-o 在一个 Transformer 里混自回归与离散扩散。后课 Transfusion 用「下一步 + 扩散」写进同一前向。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理解要 <a href="/llm/clip">CLIP</a> / SigLIP 式连续 patch + <a href="/llm/llava-projector">LLaVA 投影器</a>，好绑定与 OCR。生成若用同一连续向量，没有 softmax 词表；若共用 VQ 编码器，理解掉细节。强行单编码器是零和。Janus 的回答是解耦：理解走连续视觉塔，生成走离散塔，语言骨干共享。Show-o 把理解当 AR 文本（含连续或离散视觉），生成用掩码离散扩散，仍一张网。</p><p><span class="marginnote">术语翻译：VQ 码本就像给照片做「调色板编号」——把图像切成小块，每块用密码本里最像的条目编号代替。一串编号就能当 token 让语言模型预测，代价是小字、细纹理这类信息在编码时就被抹掉了，OCR 掉点正是出在这里。</span></p><p>Chameleon 把图文都离散化进同一词表，接口干净，理解侧付量化税。</p>',7)),(e(),s(l,null,{default:E(()=>[t(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%80%8E%E4%B9%88%E7%BB%9F%E4%B8%80%E8%B0%88%E5%9B%BE%E4%B8%8E%E9%80%A0%E5%9B%BE%3F%22%5D%20--%3E%20J%5B%22Janus%EF%BC%9A%E5%8F%8C%E5%A1%94%E8%A7%A3%E8%80%A6%20%C2%B7%20LLM%20%E5%85%B1%E4%BA%AB%22%5D%0A%20%20Q%20--%3E%20SO%5B%22Show-o%EF%BC%9A%E5%8D%95%E5%A1%94%E6%B7%B7%20AR%20%2B%20%E6%8E%A9%E7%A0%81%E6%89%A9%E6%95%A3%22%5D%0A%20%20Q%20--%3E%20CH%5B%22Chameleon%EF%BC%9A%E5%9B%BE%E6%96%87%E5%85%A8%E7%A6%BB%E6%95%A3%E5%90%8C%E4%B8%80%E8%AF%8D%E8%A1%A8%22%5D%0A%20%20J%20--%3E%20J1%5B%22%E7%90%86%E8%A7%A3%E4%B8%8D%E8%A2%AB%E9%87%8F%E5%8C%96%E4%BC%A4%20%C2%B7%20%E4%BB%98%E5%8F%8C%E4%BB%BD%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20SO%20--%3E%20S1%5B%22%E4%B8%80%E5%BC%A0%E7%BD%91%20%C2%B7%20%E9%9D%A0%E7%9B%AE%E6%A0%87%E5%8A%A0%E6%9D%83%E9%98%B2%E4%B8%80%E8%BE%B9%E5%80%92%22%5D%0A%20%20CH%20--%3E%20C1%5B%22%E6%8E%A5%E5%8F%A3%E6%9C%80%E5%B9%B2%E5%87%80%20%C2%B7%20%E7%90%86%E8%A7%A3%E4%BB%98%E9%87%8F%E5%8C%96%E7%A8%8E%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p><span class="marginnote">「统一」要声明统一的是权重、词表，还是训练混合。只把两个专家接在一个聊天入口，不是本课的统一模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选接口：双塔（Janus）、混合目标单塔（Show-o / 后课 Transfusion）、全离散词表（Chameleon）。训练必须两任务混合，否则共享 LLM 会被一方洗掉。评测分列：POPE / VQA 与 FID / 文生图，禁止用单一「全能分」。视觉前端理解侧仍应是 <a href="/llm/vit-as-encoder">ViT</a> 连续特征。</p><p><span class="marginnote">常见误区：用一个「全能分」给统一模型排名。只测文生图会漏掉它其实看不清图里的字；只测 VQA 会漏掉它生成的图早就崩了。理解与生成必须分列汇报——历史上好几个「统一」模型就是靠单项好看掩盖另一侧退化。</span></p>',4)),(e(),s(l,null,{default:E(()=>[t(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIX%5B%22%E5%83%8F%E7%B4%A0%22%5D%20--%3E%20UND%5B%22%E7%90%86%E8%A7%A3%E7%BC%96%E7%A0%81%E5%99%A8%20%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20PIX%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E7%BC%96%E7%A0%81%E5%99%A8%20%E7%A6%BB%E6%95%A3%E6%88%96%E6%8E%A9%E7%A0%81%22%5D%0A%20%20UND%20--%3E%20LLM%5B%22%E5%85%B1%E4%BA%AB%20LLM%22%5D%0A%20%20GEN%20--%3E%20LLM%0A%20%20LLM%20--%3E%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%0A%20%20LLM%20--%3E%20IMG%5B%22%E5%9B%BE%E5%83%8F%E7%A0%81%E6%88%96%E6%89%A9%E6%95%A3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>解耦让梯度不再穿越同一视觉瓶颈：理解损失更新连续塔，生成损失更新码塔，LLM 学两套前缀语法。代价是参数与协议双份，以及「图既当输入又当输出」时两塔要对齐语义。单塔混合则靠目标加权，避免一种损失主导。</p><p><span class="marginnote">直觉类比：Janus 的共享 LLM 像一位双语经理——两位翻译（连续塔、离散塔）各自把图「翻译」成他能读的话，经理本人不用学看图；代价是公司要养两位翻译。单塔方案则是一位翻译硬吃两种语言，省人但容易顾此失彼。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>双塔不是端到端世界模型。下一课把文本 CE 与图像扩散写进同一次 Transformer 计算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>统一模型必须显式处理理解连续与生成离散的冲突。</li><li>Janus 解耦编码器；Show-o 混合 AR 与掩码扩散。</li><li>评测必须分列理解和生成。</li><li>出处：Janus；Show-o；Chameleon。</li></ul>',7))])}const D=i(d,[["render",h]]);export{c as __pageData,D as default};
